
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_revm11_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_revm11", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.695051469950678e+00, -2.619222145767312e+00, -2.514742215787991e+00, -2.374206612065844e+00, -2.192826284325376e+00, -1.975897541137442e+00, -1.753338365074798e+00, -1.590342117309020e+00, -1.515825549751364e+00, -1.309251363049491e+00, -8.343624217418311e-01, -4.445418578751626e-01, -2.917222965103741e-01, -2.153579367671480e-01, -1.539122294383913e-01, -6.752662842128489e-02, -1.284384035012641e-02, -1.043256121812400e-03, -1.155687769712443e-05, -1.588787268363128e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


